// One item per supported file. Small images in emails (logos, signatures) are skipped.
const settings = $('Finance Settings').first().json;
const ALLOWED = /^(application\/pdf|image\/(jpeg|png|webp))$/i;
const bytes = s => { const m = String(s || '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)/); if (!m) return 0; return Number(m[1]) * ({ B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 })[m[2]]; };
const fromEmail = $('New Finance Email').isExecuted;
const out = [];
// read the trigger items: the Set node before this one does not pass files on
const source = fromEmail ? $('New Finance Email').all() : $('Upload Form').all();
for (const item of source) {
  const j = item.json;
  const meta = fromEmail
    ? { source: 'Email from ' + (j.from?.text ?? j.from ?? ''), subject: j.subject ?? '', type_hint: 'auto', note: '' }
    : { source: 'Upload form', subject: '', type_hint: String(j.type ?? 'auto'), note: String(j.note ?? '') };
  for (const bin of Object.values(item.binary ?? {})) {
    if (!ALLOWED.test(bin.mimeType || '')) continue;
    if (fromEmail && bin.mimeType.startsWith('image/') && bytes(bin.fileSize) < 15000) continue;
    out.push({ json: { ...meta, file_name: bin.fileName || 'document', mime_type: bin.mimeType, settings }, binary: { data: bin } });
  }
}
return out;

// Validates each extraction, detects duplicates and builds the Transactions row.
const cfg = $('Finance Settings').first().json;
const cats = String(cfg.categories).split(',').map(s => s.trim());
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const seen = new Set($('Read Transactions').all().map(i => i.json['Dedupe Key']).filter(Boolean));
const today = DateTime.now().startOf('day');
const results = $('Read Each File').all().map(i => i.json);
const COLS = ['Txn ID', 'Date', 'Type', 'Document Type', 'Category', 'Party', 'Party Email', 'Invoice No', 'Description', 'Subtotal', 'Tax', 'Total', 'Currency', 'Due Date', 'Payment Status', 'Status', 'Issues', 'Confidence', 'Source', 'File', 'Dedupe Key', 'Recorded At'];
const blank = Object.fromEntries(COLS.map(c => [c, '']));
return results.map((r, idx) => {
  const d = r.extraction;
  const base = { file: r.file_name, link: r.drive_link, source: r.source };
  if (!d || typeof d !== 'object') {
    const issue = 'The AI could not read this file' + (r.ai_error ? ': ' + r.ai_error : '');
    return { json: { ...base, Status: 'Needs review', Issues: issue, row: { ...blank, 'Txn ID': 'TX-' + DateTime.now().toFormat('yyyyMMdd') + '-' + $execution.id + '-' + (idx + 1), 'Status': 'Needs review', 'Issues': issue, 'Source': r.source, 'File': r.drive_link, 'Recorded At': DateTime.now().toISO() } } };
  }
  if (!d.is_financial_document || d.document_type === 'other') return { json: { ...base, Status: 'Ignored', Issues: 'Not an invoice or receipt', row: null } };
  const party = d.direction === 'income' ? d.customer_name : d.vendor_name;
  const key = norm(party) + '|' + (d.invoice_number ? norm(d.invoice_number) : d.issue_date) + '|' + Math.round(Number(d.total) || 0);
  if (seen.has(key)) return { json: { ...base, Status: 'Duplicate', Issues: 'Already recorded (' + party + ', ' + (d.invoice_number || d.issue_date) + ')', row: null } };
  seen.add(key);
  const issues = [];
  const total = Number(d.total) || 0, sub = Number(d.subtotal) || 0, tax = Number(d.tax_amount) || 0;
  if (total <= 0) issues.push('total missing');
  if (sub > 0 && Math.abs(sub + tax - total) > Math.max(1, total * 0.01)) issues.push('subtotal + tax does not match total');
  const date = DateTime.fromISO(d.issue_date || '');
  if (!date.isValid) issues.push('issue date unreadable');
  else if (date > today.plus({ days: 1 }) || date < today.minus({ years: 2 })) issues.push('issue date ' + d.issue_date + ' looks wrong');
  if (!(Number(d.confidence) >= Number(cfg.review_below_confidence))) issues.push('low confidence (' + d.confidence + ')');
  const category = cats.includes(d.category) ? d.category : 'Other';
  const status = issues.length ? 'Needs review' : 'Recorded';
  return { json: { ...base, Status: status, Issues: issues.join('; '), row: {
    'Txn ID': 'TX-' + DateTime.now().toFormat('yyyyMMdd') + '-' + $execution.id + '-' + (idx + 1),
    'Date': date.isValid ? date.toISODate() : '',
    'Type': d.direction === 'income' ? 'Income' : 'Expense',
    'Document Type': d.document_type,
    'Category': category,
    'Party': party || '',
    'Party Email': d.customer_email || '',
    'Invoice No': d.invoice_number || '',
    'Description': d.description || '',
    'Subtotal': sub,
    'Tax': tax,
    'Total': total,
    'Currency': d.currency || cfg.default_currency,
    'Due Date': d.due_date || '',
    'Payment Status': d.payment_status === 'paid' ? 'Paid' : d.payment_status === 'unpaid' ? 'Unpaid' : 'Unknown',
    'Status': status,
    'Issues': issues.join('; '),
    'Confidence': Number(d.confidence) || 0,
    'Source': r.source,
    'File': r.drive_link,
    'Dedupe Key': key,
    'Recorded At': DateTime.now().toISO(),
  } } };
});

