// Picks unpaid invoices that reached their next reminder stage and renders the email.
const cfg = $('Reminder Settings').first().json;
const stages = String(cfg.reminder_days).split(',').map(Number).filter(n => n >= 0);
const today = DateTime.now().startOf('day');
const out = [];
for (const i of $input.all()) {
  const inv = i.json;
  if (!inv['Invoice No'] || !inv['Client Email'] || ['Paid', 'Cancelled'].includes(inv.Status)) continue;
  const due = DateTime.fromISO(String(inv['Due Date'] || ''));
  if (!due.isValid) continue;
  const days = Math.floor(today.diff(due.startOf('day'), 'days').days);
  const sent = Number(inv['Reminders Sent'] || 0);
  if (sent >= stages.length || days < stages[sent]) continue;
  if (inv['Last Reminder At'] && DateTime.fromISO(inv['Last Reminder At']).hasSame(today, 'day')) continue;
  const stage = sent + 1;
  const amount = Number(inv.Amount || 0).toLocaleString('id-ID') + ' ' + (inv.Currency || '');
  const fill = t => String(t).replace(/\{client\}/g, inv.Client || 'there').replace(/\{invoice\}/g, inv['Invoice No']).replace(/\{amount\}/g, amount)
    .replace(/\{due_date\}/g, due.toFormat('d LLL yyyy')).replace(/\{days\}/g, String(days)).replace(/\{payment_details\}/g, cfg.payment_details)
    .replace(/\{sender\}/g, cfg.sender_name).replace(/\{business\}/g, cfg.business_name);
  out.push({ json: { invoice: inv['Invoice No'], to: inv['Client Email'], cc: stage === stages.length ? cfg.owner_email : '', stage, subject: fill(cfg['subject_' + Math.min(stage, 3)]), body: fill(cfg['body_' + Math.min(stage, 3)]) } });
}
return out;

// Last week's cash in and out, the week before, bills and receivables.
const cfg = $('Report Settings').first().json;
const cur = cfg.currency;
const tx = $('Load Transactions').all().map(i => i.json).filter(r => r['Txn ID'] && r.Status === 'Recorded' && (r.Currency || cur) === cur);
const review = $('Load Transactions').all().filter(i => i.json.Status === 'Needs review').length;
const inv = $('Load Invoices').all().map(i => i.json).filter(r => r['Invoice No'] && !['Paid', 'Cancelled'].includes(r.Status));
const thisWeek = DateTime.now().startOf('week');
const win = (from, to) => r => { const d = DateTime.fromISO(String(r.Date)); return d.isValid && d >= from && d < to; };
const lastWeek = win(thisWeek.minus({ weeks: 1 }), thisWeek);
const weekBefore = win(thisWeek.minus({ weeks: 2 }), thisWeek.minus({ weeks: 1 }));
const sum = rows => rows.reduce((s, r) => s + (Number(r.Total) || 0), 0);
const paidIn = f => tx.filter(r => r.Type === 'Income' && r['Payment Status'] === 'Paid' && f(r));
const paidOut = f => tx.filter(r => r.Type === 'Expense' && r['Payment Status'] !== 'Unpaid' && f(r));
const cashIn = sum(paidIn(lastWeek)), cashOut = sum(paidOut(lastWeek));
const prevIn = sum(paidIn(weekBefore)), prevOut = sum(paidOut(weekBefore));
const byCat = {};
for (const r of paidOut(lastWeek)) byCat[r.Category || 'Other'] = (byCat[r.Category || 'Other'] || 0) + (Number(r.Total) || 0);
const today = DateTime.now().startOf('day');
const bills = tx.filter(r => r.Type === 'Expense' && r['Payment Status'] === 'Unpaid' && r['Due Date'])
  .filter(r => { const d = DateTime.fromISO(String(r['Due Date'])); return d.isValid && d <= today.plus({ days: 7 }); })
  .map(r => ({ party: r.Party, total: Number(r.Total) || 0, due: r['Due Date'], overdue: DateTime.fromISO(String(r['Due Date'])) < today }));
const ar = inv.map(r => ({ client: r.Client, total: Number(r.Amount) || 0, due: r['Due Date'], overdue: DateTime.fromISO(String(r['Due Date'])) < today }));
return [{ json: {
  period: thisWeek.minus({ weeks: 1 }).toFormat('d LLL') + ' – ' + thisWeek.minus({ days: 1 }).toFormat('d LLL yyyy'),
  currency: cur, cash_in: cashIn, cash_out: cashOut, net: cashIn - cashOut, prev_in: prevIn, prev_out: prevOut, prev_net: prevIn - prevOut,
  top_expenses: Object.entries(byCat).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([category, total]) => ({ category, total })),
  bills_due: bills, bills_due_total: bills.reduce((s, b) => s + b.total, 0),
  receivables_overdue: ar.filter(a => a.overdue), receivables_overdue_total: ar.filter(a => a.overdue).reduce((s, a) => s + a.total, 0),
  receivables_open_total: ar.reduce((s, a) => s + a.total, 0), needs_review: review,
} }];

