={{ (() => {
  const c = $('Compute Cash Flow').first().json;
  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const m = n => Number(n || 0).toLocaleString('id-ID');
  const delta = (a, b) => b ? ' <span style="color:#666">(' + (a >= b ? '+' : '') + Math.round((a - b) / Math.abs(b) * 100) + '% vs week before)</span>' : '';
  const note = $json.text ? '<p style="background:#f6f6f6;padding:10px">' + esc($json.text) + '</p>' : '';
  return '<div style="font-family:Arial,sans-serif;font-size:14px"><h3 style="margin:0">' + esc(c.period) + '</h3>' + note +
    '<table cellpadding="6" style="border-collapse:collapse;border:1px solid #ddd">' +
    '<tr><td>Cash in</td><td align="right">' + m(c.cash_in) + '</td><td>' + delta(c.cash_in, c.prev_in) + '</td></tr>' +
    '<tr><td>Cash out</td><td align="right">' + m(c.cash_out) + '</td><td>' + delta(c.cash_out, c.prev_out) + '</td></tr>' +
    '<tr><td><b>Net</b></td><td align="right"><b>' + m(c.net) + '</b></td><td>' + esc(c.currency) + '</td></tr></table>' +
    (c.top_expenses.length ? '<h4>Top expenses</h4><ul>' + c.top_expenses.map(e => '<li>' + esc(e.category) + ': ' + m(e.total) + '</li>').join('') + '</ul>' : '') +
    '<h4>Bills due within 7 days: ' + m(c.bills_due_total) + '</h4><ul>' + c.bills_due.map(b => '<li>' + esc(b.party) + ' · ' + m(b.total) + ' · ' + esc(b.due) + (b.overdue ? ' <b style="color:#b00020">overdue</b>' : '') + '</li>').join('') + '</ul>' +
    '<h4>Receivables: ' + m(c.receivables_open_total) + ' open, ' + m(c.receivables_overdue_total) + ' overdue</h4><ul>' + c.receivables_overdue.map(a => '<li>' + esc(a.client) + ' · ' + m(a.total) + ' · due ' + esc(a.due) + '</li>').join('') + '</ul>' +
    (c.needs_review ? '<p><b>' + c.needs_review + ' documents need review</b> in the Transactions tab.</p>' : '') + '</div>';
})() }}

